func HasPricePlan() predicate.ModelPriceWindow {
	return predicate.ModelPriceWindow(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, PricePlanTable, PricePlanColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPricePlanWith applies the HasEdge predicate on the "price_plan" edge with a given conditions (other predicates).
func HasPricePlanWith(preds ...predicate.ModelPricePlan) predicate.ModelPriceWindow {
	return predicate.ModelPriceWindow(func(s *sql.Selector) {
		step := newPricePlanStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ModelPriceWindow) predicate.ModelPriceWindow {
	return predicate.ModelPriceWindow(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ModelPriceWindow) predicate.ModelPriceWindow {
	return predicate.ModelPriceWindow(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ModelPriceWindow) predicate.ModelPriceWindow {
	return predicate.ModelPriceWindow(sql.NotPredicates(p))
}
